create or replace function public.create_my_shop(p_name text, p_city text default null, p_country text default 'Congo', p_currency text default 'XAF') returns public.shops language plpgsql security invoker set search_path='' as $$ declare v_shop public.shops; begin if auth.uid() is null then raise exception 'Authentication required'; end if; insert into public.shops(owner_id,name,city,country,currency) values(auth.uid(),trim(p_name),nullif(trim(p_city),''),coalesce(nullif(trim(p_country),''),'Congo'),coalesce(nullif(trim(p_currency),''),'XAF')) returning * into v_shop; return v_shop; end; $$; grant execute on function public.create_my_shop(text,text,text,text) to authenticated;
